      userdoc: {
        version: 1,
        kind: "user",
        methods: {
          "GUARDIAN()": {
            notice:
              "Getter function for the address of the guardian.         Public getter is legacy and will be removed in the future. Use `SuperchainConfig.guardian()` instead.",
          },
          "L2_ORACLE()": {
            notice:
              "Getter function for the contract of the L2OutputOracle on this chain.         Public getter is legacy and will be removed in the future. Use `l2Oracle()` instead.",
          },
          "SYSTEM_CONFIG()": {
            notice:
              "Getter function for the contract of the SystemConfig on this chain.         Public getter is legacy and will be removed in the future. Use `systemConfig()` instead.",
          },
          constructor: { notice: "Constructs the OptimismPortal contract." },
          "depositTransaction(address,uint256,uint64,bool,bytes)": {
            notice:
              "Accepts deposits of ETH and data, and emits a TransactionDeposited event for use in         deriving deposit transactions. Note that if a deposit is made by a contract, its         address will be aliased when retrieved using `tx.origin` or `msg.sender`. Consider         using the CrossDomainMessenger contracts for a simpler developer experience.",
          },
          "donateETH()": {
            notice:
              "Accepts ETH value without triggering a deposit to L2.         This function mainly exists for the sake of the migration between the legacy         Optimism system and Bedrock.",
          },
          "finalizeWithdrawalTransaction((uint256,address,address,uint256,uint256,bytes))":
            { notice: "Finalizes a withdrawal transaction." },
          "finalizedWithdrawals(bytes32)": {
            notice:
              "A list of withdrawal hashes which have been successfully finalized.",
          },
          "guardian()": {
            notice:
              "Getter function for the address of the guardian.         Public getter is legacy and will be removed in the future. Use `SuperchainConfig.guardian()` instead.",
          },
          "initialize(address,address,address)": { notice: "Initializer." },
          "isOutputFinalized(uint256)": {
            notice:
              "Determine if a given output is finalized.         Reverts if the call to l2Oracle.getL2Output reverts.         Returns a boolean otherwise.",
          },
          "l2Oracle()": { notice: "Contract of the L2OutputOracle." },
          "l2Sender()": {
            notice:
              "Address of the L2 account which initiated a withdrawal in this transaction.         If the of this variable is the default L2 sender address, then we are NOT inside of         a call to finalizeWithdrawalTransaction.",
          },
          "minimumGasLimit(uint64)": {
            notice:
              "Computes the minimum gas limit for a deposit.         The minimum gas limit linearly increases based on the size of the calldata.         This is to prevent users from creating L2 resource usage without paying for it.         This function can be used when interacting with the portal to ensure forwards         compatibility.",
          },
          "params()": { notice: "EIP-1559 style gas parameters." },
          "paused()": { notice: "Getter for the current paused status." },
          "proveWithdrawalTransaction((uint256,address,address,uint256,uint256,bytes),uint256,(bytes32,bytes32,bytes32,bytes32),bytes[])":
            { notice: "Proves a withdrawal transaction." },
          "provenWithdrawals(bytes32)": {
            notice:
              "A mapping of withdrawal hashes to `ProvenWithdrawal` data.",
          },
          "superchainConfig()": {
            notice: "Contract of the Superchain Config.",
          },
          "systemConfig()": { notice: "Contract of the SystemConfig." },
          "version()": { notice: "Semantic version." },
        },
        events: {
          "TransactionDeposited(address,address,uint256,bytes)": {
            notice:
              "Emitted when a transaction is deposited from L1 to L2.         The parameters of this event are read by the rollup node and used to derive deposit         transactions on L2.",
          },
          "WithdrawalFinalized(bytes32,bool)": {
            notice: "Emitted when a withdrawal transaction is finalized.",
          },
          "WithdrawalProven(bytes32,address,address)": {
            notice: "Emitted when a withdrawal transaction is proven.",
          },
        },
        notice:
          "The OptimismPortal is a low-level contract responsible for passing messages between L1         and L2. Messages sent directly to the OptimismPortal have no form of replayability.         Users are encouraged to use the L1CrossDomainMessenger for a higher-level interface.",
      },
